"use strict";(self.webpackChunkwoocommerce_marketplace_shopify_connector_doc=self.webpackChunkwoocommerce_marketplace_shopify_connector_doc||[]).push([[383],{537(t,e,o){o.r(e),o.d(e,{_pageData:()=>r,default:()=>s});var n=o(641);const r=JSON.parse('{"path":"/shopify-connector/connecting-your-store.html","title":"Connecting Your Store","lang":"en-US","frontmatter":{"title":"Connecting Your Store","description":"The Shopify Account List, the store switcher, adding a store outside the wizard, editing a connection and removing one."},"git":{},"filePathRelative":"shopify-connector/connecting-your-store.md"}'),a={name:"connecting-your-store.md"},s=(0,o(6262).A)(a,[["render",function(t,e,o,r,a,s){const i=(0,n.g2)("RouteLink");return(0,n.uX)(),(0,n.CE)("div",null,[e[3]||(e[3]=(0,n.Fv)('<h1 id="connecting-your-store" tabindex="-1"><a class="header-anchor" href="#connecting-your-store"><span>Connecting Your Store</span></a></h1><p><strong>My Account → Shopify Connector</strong> is the seller&#39;s home for every Shopify store they have connected. Everything else in the connector is reached from here.</p><h2 id="the-shopify-account-list" tabindex="-1"><a class="header-anchor" href="#the-shopify-account-list"><span>The Shopify Account List</span></a></h2><p><img src="/woocommerce-marketplace-shopify-connector/images/shopify-connector/account-list.png" alt="The Shopify Account List with two connected stores, bulk actions and the view switcher"></p><p>Each row shows:</p><table><thead><tr><th>Column</th><th>What it tells you</th></tr></thead><tbody><tr><td><strong>Store Name</strong></td><td>The store&#39;s name, its connector account <strong>ID</strong>, and the row actions <em>Edit</em> and <em>Delete</em></td></tr><tr><td><strong>Shopify User ID</strong></td><td>The store&#39;s numeric ID in Shopify</td></tr><tr><td><strong>Action</strong></td><td><strong>Manage Account</strong> — opens the nine configuration tabs</td></tr><tr><td><strong>Status</strong></td><td><strong>Connected</strong> or <strong>Disconnected</strong>, checked live</td></tr></tbody></table><p>The <strong>Status</strong> badge is not stored. Each time the list loads, the connector asks Shopify for the store&#39;s name and compares it with the name saved here. A <strong>Disconnected</strong> badge means the store did not answer, the token has been revoked, or the store was renamed in Shopify.</p><p>Ten accounts are listed per page; a pager appears below the table when there are more.</p><h3 id="list-and-grid-views" tabindex="-1"><a class="header-anchor" href="#list-and-grid-views"><span>List and grid views</span></a></h3><p>The two small buttons above the table on the right switch between the table and a card layout. Both show the same information and support the same bulk actions.</p><p><img src="/woocommerce-marketplace-shopify-connector/images/shopify-connector/account-list-grid.png" alt="The account list in grid view, showing each connected store as a card"></p><h2 id="switching-between-stores" tabindex="-1"><a class="header-anchor" href="#switching-between-stores"><span>Switching between stores</span></a></h2><p>When a seller has more than one Shopify store, the pill at the top right of the connector header shows the active one — its name, account ID and domain, with a green dot for a live connection.</p><p><img src="/woocommerce-marketplace-shopify-connector/images/shopify-connector/store-switcher.png" alt="The store switcher dropdown open, listing the seller&#39;s connected Shopify accounts"></p><p>Selecting the pill drops down the full list. Choose a store to jump straight into its Manage Account screen, or select <strong>+ Add Account</strong> to connect another one.</p><h2 id="the-navigation-panel" tabindex="-1"><a class="header-anchor" href="#the-navigation-panel"><span>The navigation panel</span></a></h2><p>The ☰ button beside the connector title opens a side panel with the same navigation in a taller form: <strong>Account List</strong>, <strong>Add Account</strong>, a <strong>Connected Accounts</strong> section with one card per store, and a <strong>Manage Settings</strong> shortcut to the active store&#39;s Settings tab.</p><p><img src="/woocommerce-marketplace-shopify-connector/images/shopify-connector/connector-sidebar.png" alt="The connector navigation panel open, showing Account List, Add Account and the connected accounts"></p><p>This is the panel sellers use on narrow screens, where the header pill collapses.</p><h2 id="adding-a-shopify-account" tabindex="-1"><a class="header-anchor" href="#adding-a-shopify-account"><span>Adding a Shopify account</span></a></h2><p>Select <strong>Add Account</strong> — from the button at the top right of the list, from the store switcher, or from the navigation panel. The form offers the same two authentication methods as the wizard.</p><p><img src="/woocommerce-marketplace-shopify-connector/images/shopify-connector/add-account-oauth.png" alt="The Add Shopify Account form on the Dev Dashboard App (OAuth) tab"></p><h3 id="dev-dashboard-app-oauth" tabindex="-1"><a class="header-anchor" href="#dev-dashboard-app-oauth"><span>Dev Dashboard App (OAuth)</span></a></h3><ol><li><p>Copy the two redirect URIs from the blue callout into the Shopify app&#39;s <strong>Allowed redirection URLs</strong>.</p></li><li><p>Fill in:</p><table><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Store Name</strong></td><td>Must match the Shopify store name exactly</td></tr><tr><td><strong>Domain Name</strong></td><td>The <code>myshopify.com</code> domain, without <code>https://</code></td></tr><tr><td><strong>App Client ID</strong></td><td>From the Shopify Developer Dashboard app</td></tr><tr><td><strong>App Secret Key</strong></td><td>From the same app</td></tr></tbody></table></li><li><p>Select <strong>Connect Your Account</strong>. Shopify&#39;s authorisation screen opens; approve the app.</p></li></ol><p>On success the connector returns to the account list with a green <strong>✔ Shopify Account connected successfully!</strong> banner, and the store&#39;s three webhooks have already been registered.</p><h3 id="legacy-custom-app" tabindex="-1"><a class="header-anchor" href="#legacy-custom-app"><span>Legacy Custom App</span></a></h3><p><img src="/woocommerce-marketplace-shopify-connector/images/shopify-connector/add-account-legacy.png" alt="The Add Shopify Account form on the Legacy Custom App tab"></p><p>Select the <strong>Legacy Custom App</strong> tab and fill in <strong>Store Name</strong>, <strong>API Token</strong>, <strong>Domain Name</strong> and <strong>API Secret Key</strong>, then select <strong>Connect Legacy Account</strong>. There is no redirect — the connector verifies the token with Shopify and saves the account immediately.</p><div class="hint-container important"><p class="hint-container-title">Important</p><p>The <strong>API Secret Key</strong> is what the connector uses to verify incoming Shopify webhooks. If it is wrong, the store connects but real-time updates are silently rejected.</p></div><h3 id="errors-on-this-form" tabindex="-1"><a class="header-anchor" href="#errors-on-this-form"><span>Errors on this form</span></a></h3><table><thead><tr><th>Message</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>&quot;Please Enter All Required Details.&quot;</td><td>A required field is blank</td><td>Complete every field</td></tr><tr><td>&quot;Added store name does not match with the shopify store name. Please add valid store name.&quot;</td><td>Store Name differs from the name in Shopify</td><td>Copy the name from Shopify exactly</td></tr><tr><td>&quot;Please Enter Your Correct Shopify Account Details.&quot;</td><td>Shopify rejected the credentials</td><td>Re-copy the Client ID, secret or token</td></tr><tr><td>&quot;Account already exists.&quot;</td><td>This Shopify store is already connected</td><td>Manage the existing account instead</td></tr><tr><td><code>Invalid OAuth state</code></td><td>The authorisation round trip was interrupted or tampered with</td><td>Start again from <strong>Add Account</strong></td></tr></tbody></table><h2 id="editing-a-connection" tabindex="-1"><a class="header-anchor" href="#editing-a-connection"><span>Editing a connection</span></a></h2><p>Select <strong>Manage Account</strong> on a row (or <strong>Edit</strong> in the row actions) and open the <strong>Account</strong> tab.</p><p><img src="/woocommerce-marketplace-shopify-connector/images/shopify-connector/manage-account-details.png" alt="The Account tab of a connected store, showing the credential fields and the masked token"></p><table><thead><tr><th>Field</th><th>Editable</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Store Name</strong></td><td>Yes</td><td>Must still match Shopify</td></tr><tr><td><strong>Domain Name</strong></td><td>No</td><td>Fixed for the life of the connection</td></tr><tr><td><strong>App Client ID</strong></td><td>Depends</td><td>Read-only once an OAuth connection is established</td></tr><tr><td><strong>App Client Secret</strong></td><td>Yes</td><td>Needed for webhook verification</td></tr><tr><td><strong>Token</strong></td><td>No</td><td>Generated and saved automatically; shown masked</td></tr><tr><td><strong>Account Type</strong></td><td>Yes</td><td><strong>App Dev Dashboard</strong> or <strong>Legacy Custom App</strong></td></tr></tbody></table><p>The button at the bottom changes with the account type:</p><ul><li><strong>App Dev Dashboard</strong> → <strong>Refresh the app details</strong>. This re-runs the Shopify authorisation. Use it after publishing a new version of the app in the Developer Dashboard; as the on-screen note says, the app only starts working to the new version once the details are refreshed.</li><li><strong>Legacy Custom App</strong> → <strong>Update Details</strong>. This re-validates the store name against Shopify and saves.</li></ul><h2 id="removing-a-connection" tabindex="-1"><a class="header-anchor" href="#removing-a-connection"><span>Removing a connection</span></a></h2><p>Select <strong>Delete</strong> in a row&#39;s actions, or tick one or more rows and use the <strong>Bulk actions → Delete</strong> control. A confirmation appears first.</p><p><img src="/woocommerce-marketplace-shopify-connector/images/shopify-connector/account-delete-confirm.png" alt="The delete confirmation modal, warning that disconnecting stops real-time updates"></p><p>Deleting an account removes the connection and everything the connector stored for it: the product and order mappings, the category mappings, the price rules and the account&#39;s settings.</p><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>Deleting a Shopify account does <strong>not</strong> delete the WooCommerce products and orders that were imported through it. Those stay in your store, but they are no longer linked to Shopify, so reconnecting the same store later will import them again as new items.</p></div><p>The modal notes that a store can be reconnected at any time to resume syncing.</p><h2 id="next-step" tabindex="-1"><a class="header-anchor" href="#next-step"><span>Next step</span></a></h2>',44)),(0,n.Lk)("p",null,[e[1]||(e[1]=(0,n.eW)("With a store connected, line up the catalogue structure first — see ",-1)),(0,n.bF)(i,{to:"/shopify-connector/category-mapping.html"},{default:(0,n.k6)(()=>[...e[0]||(e[0]=[(0,n.eW)("Category Mapping",-1)])]),_:1}),e[2]||(e[2]=(0,n.eW)(".",-1))])])}]])}}]);